import{_ as a,o as e,c as n,ai as t}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"AI Coding 工作流","description":"","frontmatter":{},"headers":[],"relativePath":"ai/dev/coding/cursor-workflow.md","filePath":"ai/dev/coding/cursor-workflow.md"}'),r={name:"ai/dev/coding/cursor-workflow.md"};function i(p,s,l,d,o,h){return e(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="ai-coding-工作流" tabindex="-1">AI Coding 工作流 <a class="header-anchor" href="#ai-coding-工作流" aria-label="Permalink to “AI Coding 工作流”">​</a></h1><blockquote><p>我如何把 AI 纳入真实的软件开发闭环。不是 Cursor 按钮说明书。</p></blockquote><p>本页是 AI Coding 栏目的<strong>唯一阶段总地图</strong>。不讲 Prompt 全文，不放文件模板，也不做项目实战。</p><h3 id="什么时候用" tabindex="-1">什么时候用？ <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用？”">​</a></h3><p>当你要把一个真实开发任务放进闭环，而不是单独让 AI 写一段代码时。</p><p>新项目从需求进入。老项目从读代码进入，<strong>不重做架构</strong>。这不是漏了一步，分叉见文末。</p><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to “目标”">​</a></h3><p>形成可重复的总流程（不必每次从零重读）：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>需求 → 拆解 → 架构 → Context → Rules → Spec</span></span>
<span class="line"><span> → 实现 → 测试 → Review → Debug / 回归 → 交付</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>核心原则：</p><blockquote><p><strong>AI 可以提高代码生产速度，但不能替代开发者对需求、架构、质量和最终结果负责。</strong></p></blockquote><hr><h2 id="完整闭环" tabindex="-1">完整闭环 <a class="header-anchor" href="#完整闭环" aria-label="Permalink to “完整闭环”">​</a></h2><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1. 明确需求</span></span>
<span class="line"><span>2. 拆解任务</span></span>
<span class="line"><span>3. 架构</span></span>
<span class="line"><span>4. Context</span></span>
<span class="line"><span>5. Rules</span></span>
<span class="line"><span>6. Spec</span></span>
<span class="line"><span>7. 实现</span></span>
<span class="line"><span>8. 测试</span></span>
<span class="line"><span>9. Review</span></span>
<span class="line"><span>10. Debug / 回归</span></span>
<span class="line"><span>11. 交付</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>重构不在主链上。没有新的 Spec，就不重构。</p><hr><h2 id="_1-明确需求" tabindex="-1">1. 明确需求 <a class="header-anchor" href="#_1-明确需求" aria-label="Permalink to “1. 明确需求”">​</a></h2><p><strong>解决：</strong> 要解决什么问题？给谁用？怎样算有用？</p><p>验收标准和「不做什么」留到 Spec，这里不写成任务说明书。</p><p>AI 最容易「自作主张扩 scope」。问题没说清时，生成再快也是在制造返工。</p><p><strong>人：</strong> 决定业务上该不该做。<br><strong>AI：</strong> 不决定。可以帮你把含糊的描述问清楚，不能替你拍板。</p><hr><h2 id="_2-拆解任务" tabindex="-1">2. 拆解任务 <a class="header-anchor" href="#_2-拆解任务" aria-label="Permalink to “2. 拆解任务”">​</a></h2><p><strong>解决：</strong> 这一次只推进哪一刀，做完怎样能看出来？</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>读懂相关调用链</span></span>
<span class="line"><span> → 改一个接口 / 一张表 / 一个页面</span></span>
<span class="line"><span> → 再处理下一刀</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>一次只推进一类改动</li><li>每步有可观察的结果（编译过、用例过、页面能点）</li><li>先最小闭环，再谈优化</li></ul><p>拆解是工程能力，不是 Prompt 技巧。拆得清楚，AI 才稳。</p><p><strong>人：</strong> 砍 scope，决定这一刀的边界。<br><strong>AI：</strong> 可以列草案。采用哪一刀，人定。</p><hr><h2 id="_3-架构" tabindex="-1">3. 架构 <a class="header-anchor" href="#_3-架构" aria-label="Permalink to “3. 架构”">​</a></h2><p><strong>解决：</strong> 系统准备怎么解决？发生在写代码之前。</p><p>只定系统边界，例如：</p><ul><li>模块边界</li><li>技术栈</li><li>有哪些接口、哪些数据</li><li>系统级约束（分层、状态只能怎么走）</li></ul><p>不写这一次的字段校验，不写测试命令。那些属于 Spec。</p><p><strong>人：</strong> 拍板。模块是否被拆碎、是否过度设计、是否引入不必要的依赖，都不能外包。<br><strong>AI：</strong> 可以列选项。不能定架构。</p><p>老项目<strong>跳过本步</strong>。扫描到的结构是现状，不是一份新设计。跳过不等于没做架构，而是不重新设计。见文末。</p><p>做法示例在 <a href="/my-vitepress-site/ai/ai-programming/cursor-new-project.html">Cursor 新项目实战</a>，本页不展开。</p><hr><h2 id="_4-context" tabindex="-1">4. Context <a class="header-anchor" href="#_4-context" aria-label="Permalink to “4. Context”">​</a></h2><p><strong>解决：</strong> AI 需要知道这个项目现在是什么？</p><p>项目结构、技术栈、模块关系、已有的数据与接口、当前事实。不是「这一次要改什么」。</p><p><strong>人：</strong> 提供事实，或删掉扫描里的猜测。<br><strong>AI：</strong> 老项目里可以按你的范围扫描。扫出来的内容，人确认后才算 Context。</p><p>概念：<a href="/my-vitepress-site/ai/dev/coding/context-and-rules.html">Context &amp; Rules</a>。<br> 文件放哪、章节怎么写：<a href="/my-vitepress-site/ai/dev/coding/project-landing-kit.html">项目落地包</a>。本页不复制模板。</p><hr><h2 id="_5-rules" tabindex="-1">5. Rules <a class="header-anchor" href="#_5-rules" aria-label="Permalink to “5. Rules”">​</a></h2><p><strong>解决：</strong> AI 在这个项目里必须遵守什么？所有任务都适用，不是只约束这一次。</p><p>例如修改边界、分层、数据库和 API 不能擅自改、不确定就停。具体条文只维护在仓库规则里。</p><p><strong>人：</strong> 定规则，并保证它来自这个项目的真实习惯，而不是一本理想手册。<br><strong>AI：</strong> 遵守。不另写一套规范。</p><p>模板只在 <a href="/my-vitepress-site/ai/dev/coding/project-landing-kit.html">项目落地包</a>。</p><hr><h2 id="_6-spec" tabindex="-1">6. Spec <a class="header-anchor" href="#_6-spec" aria-label="Permalink to “6. Spec”">​</a></h2><p><strong>解决：</strong> 这一次要实现什么，做到什么程度才算完成？</p><p>Spec 是当前任务的冻结约定。人确认之前，不许改代码。</p><p>先分清四个词：</p><table tabindex="0"><thead><tr><th></th><th>回答</th></tr></thead><tbody><tr><td>Context</td><td>项目现在是什么</td></tr><tr><td>Rules</td><td>所有任务都要遵守什么</td></tr><tr><td>Spec</td><td>这一次做什么</td></tr><tr><td>Prompt</td><td>这一轮怎么让 AI 执行</td></tr></tbody></table><p>Prompt 用完可以扔。Spec 要留下。Prompt 不能代替 Spec。</p><p>确认时只看五件事：做什么、范围、做到什么、验收、不做什么。用不到的不写。不在这里建规格体系，也没有单独的 Spec 页。</p><p><strong>人：</strong> 确认并冻结。<br><strong>AI：</strong> 可以起草。未确认时只改措辞，不改代码。</p><p>示例将写在两篇实战里，不在本页造例子：</p><ul><li><a href="/my-vitepress-site/ai/ai-programming/cursor-new-project.html">Cursor 新项目实战</a></li><li><a href="/my-vitepress-site/ai/ai-programming/cursor-legacy-project.html">Cursor 老项目实战</a></li></ul><hr><h2 id="_7-实现" tabindex="-1">7. 实现 <a class="header-anchor" href="#_7-实现" aria-label="Permalink to “7. 实现”">​</a></h2><p><strong>解决：</strong> 按已经冻结的 Spec 把代码写出来。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Spec 已确认</span></span>
<span class="line"><span> → AI 按 Spec 改代码</span></span>
<span class="line"><span> → 人看 Diff，跑起来验证</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>尽量避免：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>一句话「帮我实现某某」</span></span>
<span class="line"><span> → AI 直接大改几十个文件</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>AI 按 Spec 实现，不按一句自然语言自由发挥。</p><p><strong>人：</strong> 收口。范围、风格、是否允许动 Spec 之外的文件，人定。<br><strong>AI：</strong> 写代码、补代码、按 Spec 生成测试草稿。</p><p>这一轮怎么提问：<a href="/my-vitepress-site/ai/dev/coding/prompt-pattern.html#_3-实现">Prompt Pattern · 实现</a>。</p><hr><h2 id="_8-测试" tabindex="-1">8. 测试 <a class="header-anchor" href="#_8-测试" aria-label="Permalink to “8. 测试”">​</a></h2><p><strong>解决：</strong> 结果是否符合 Spec 的验收标准？</p><p>能自动化的尽量自动化。没有现成测试时，至少固定一条人工验收路径。</p><p>优先看主路径和 Spec 里写明的失败路径。「测试绿了」不等于「业务对了」，尤其在 AI 大量生成代码时。</p><p>没被 Spec 点名的行为有没有被带坏，放到下一步的回归里看。本步不另写测试理论。</p><p><strong>人：</strong> 定测什么、判测试能不能抓住风险。<br><strong>AI：</strong> 可以写用例或命令草稿。</p><p>提问方式：<a href="/my-vitepress-site/ai/dev/coding/prompt-pattern.html#_6-测试">Prompt Pattern · 测试</a>。</p><hr><h2 id="_9-review" tabindex="-1">9. Review <a class="header-anchor" href="#_9-review" aria-label="Permalink to “9. Review”">​</a></h2><p><strong>解决：</strong> 这次 Diff 能不能留下？</p><p>AI 做初检，人做最终判断。重点看：</p><ul><li>Diff 本身</li><li>有没有超出 Spec</li><li>有没有违反 Rules</li><li>有没有破坏没点名的原有行为</li><li>有没有明显的质量问题</li></ul><p>写完代码才发现模块边界被破坏：在这里否决。这不是第二次架构设计，不要回到第 3 步重写一份架构。</p><blockquote><p>AI 发现的问题不一定是真的；AI 没发现也不代表没有问题。</p></blockquote><p><strong>人：</strong> 最终判断，决定改不改。<br><strong>AI：</strong> 扫 Diff，标出可疑点。</p><p>做法与 Prompt 只在 <a href="/my-vitepress-site/ai/dev/coding/ai-code-review.html">AI Code Review</a>。本页不复制。</p><hr><h2 id="_10-debug-回归" tabindex="-1">10. Debug / 回归 <a class="header-anchor" href="#_10-debug-回归" aria-label="Permalink to “10. Debug / 回归”">​</a></h2><p><strong>解决：</strong> 测试或 Review 已经指出的问题，怎样最小地修好；没点名的行为是否还在。</p><p>没有失败、也没有要守住的旧行为，就不进入 Debug。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>复现</span></span>
<span class="line"><span> → 缩小范围</span></span>
<span class="line"><span> → 看日志 / Diff / 调用链</span></span>
<span class="line"><span> → 形成假设</span></span>
<span class="line"><span> → 最小验证</span></span>
<span class="line"><span> → 再改</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>可以让 AI 辅助读栈、猜可疑点，但不要跳过复现。「再让 AI 整段重写」往往比定点修引入更多未知。</p><p>老项目尤其要证明：Spec 没有点名的行为与改前一致。这是回归，不是把系统重新测一遍。</p><p><strong>人：</strong> 决定是否修、修到哪为止。<br><strong>AI：</strong> 协助定位。不宣布「已经好了」。</p><p>提问方式：<a href="/my-vitepress-site/ai/dev/coding/prompt-pattern.html#_5-debug">Prompt Pattern · Debug</a>。没有单独的 Debug 页。</p><hr><h2 id="_11-交付" tabindex="-1">11. 交付 <a class="header-anchor" href="#_11-交付" aria-label="Permalink to “11. 交付”">​</a></h2><p><strong>解决：</strong> 这次能不能收工？</p><p>对照 Spec 勾验收，并确认「不做」没有被偷偷扩大。</p><p>至少再看一眼：</p><ul><li>Diff 里没有无关文件</li><li>说得清改了什么、为什么、怎么验</li></ul><p>复盘只记对下次有用的：哪类上下文一给就稳，哪类任务不能一次丢给 AI，哪次误报或漏报值得记住。</p><p>没有新的 Spec，就不重构。AI 很擅长「看起来更优雅」的重写；值不值、风险大不大，人判断。不在这里写发布、CI/CD 或版本流程。</p><p><strong>人：</strong> 对最终结果负责。<br><strong>AI：</strong> 不负责宣布完成。</p><hr><h2 id="新项目和老项目怎么走" tabindex="-1">新项目和老项目怎么走 <a class="header-anchor" href="#新项目和老项目怎么走" aria-label="Permalink to “新项目和老项目怎么走”">​</a></h2><p>主链相同的是后半段。入口不同。</p><p><strong>新项目</strong>从需求开始，并且要做架构：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>需求 → 拆解 → 架构 → Context → Rules → Spec → 实现 → 测试 → Review</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Context 由人按已知目标写成项目事实。</p><p><strong>老项目</strong>从已有代码开始，不重新设计架构：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>代码 → 理解 → Context → Rules → Spec → 实现 → 测试 → Review</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Context 从代码、表、接口里抽出，人删掉猜测。架构步骤整段跳过：记录现状，不产出新设计。读者若在老项目实战里看不到「架构」一节，是有意跳过，不是漏写。</p><p>两者汇合之后才是同一条：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Context → Rules → Spec → 实现 → 测试 → Review → Debug / 回归 → 交付</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>展开见 <a href="/my-vitepress-site/ai/ai-programming/cursor-new-project.html">Cursor 新项目实战</a> 与 <a href="/my-vitepress-site/ai/ai-programming/cursor-legacy-project.html">Cursor 老项目实战</a>。</p><hr><h2 id="人机分工-面试可直接说" tabindex="-1">人机分工（面试可直接说） <a class="header-anchor" href="#人机分工-面试可直接说" aria-label="Permalink to “人机分工（面试可直接说）”">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>更偏谁</th></tr></thead><tbody><tr><td>需求</td><td>人</td></tr><tr><td>任务拆解</td><td>人（可让 AI 列草案）</td></tr><tr><td>架构</td><td>人。老项目跳过，不重新设计</td></tr><tr><td>Context</td><td>人确认事实。老项目可让 AI 扫描</td></tr><tr><td>Rules</td><td>人</td></tr><tr><td>Spec</td><td>人冻结。AI 可起草</td></tr><tr><td>实现</td><td>AI 按 Spec 写，人收口</td></tr><tr><td>测试</td><td>人定测什么；草稿可 AI</td></tr><tr><td>Review</td><td>AI 初检 + 人终审</td></tr><tr><td>Debug / 回归</td><td>人</td></tr><tr><td>是否重构</td><td>人。没有新 Spec 就不重构</td></tr><tr><td>最终交付</td><td>人</td></tr></tbody></table><hr><h2 id="和「会用-cursor」的差别" tabindex="-1">和「会用 Cursor」的差别 <a class="header-anchor" href="#和「会用-cursor」的差别" aria-label="Permalink to “和「会用 Cursor」的差别”">​</a></h2><table tabindex="0"><thead><tr><th>会用工具</th><th>AI Coding 工作流</th></tr></thead><tbody><tr><td>会提问、会补全</td><td>有固定闭环与验收</td></tr><tr><td>生成得多</td><td>改得准、回得了滚</td></tr><tr><td>依赖某一款 IDE</td><td>方法可迁移到别的工具</td></tr><tr><td>出问题再问 AI</td><td>先复现、再定点、再让 AI 辅助</td></tr><tr><td>一句话就开始写</td><td>先有 Spec，再按 Spec 实现</td></tr></tbody></table><p>工具会换。这条闭环和「谁拍板」才是可迁移的。</p><hr><h2 id="我的判断" tabindex="-1">我的判断 <a class="header-anchor" href="#我的判断" aria-label="Permalink to “我的判断”">​</a></h2><p>工作流的价值不在步骤名称，而在强制一件事：</p><blockquote><p><strong>每一步都知道谁拍板、用什么验收、AI 准许动到哪里。</strong></p></blockquote><p>做到这一点，AI 才是工程放大器；做不到，只是更快地制造技术债。</p>`,128)])])}const g=a(r,[["render",i]]);export{b as __pageData,g as default};
